/**
 * Application version log. Add a new entry to the top of RELEASES for each
 * published version; the Admin Console renders this as the Version Log.
 *
 * PROCESS: RELEASES[0] must ALWAYS be the latest CUT (dated) release — the Version
 * History page marks the top entry as the current/deployed version, so a "Pending"
 * entry here would wrongly show as live. Do NOT keep an open next-release entry at
 * the top. Accrue the next release's highlights outside this file until it's cut;
 * at cut time, add its entry to the top (with `date`) and bump APP_VERSION to match.
 */
/** A changelog line. Tag it with `fb` to link it to its feedback ticket (#id). */
export type Highlight = string | { fb: number; text: string };

export interface Release {
  version: string;
  date: string;        // display date ("Pending" until the release is cut)
  publisher: string;
  highlights: Highlight[];
}

// The currently deployed (cut) release — must equal RELEASES[0].version (the top,
// dated entry). Bump only when cutting a new release.
export const APP_VERSION = "Release 4.14";

